const PER = 400;
function pageAllSchools(page){
  build();
  const totalPages = Math.ceil(SORTED.length / PER);
  const p = Math.min(Math.max(page||1,1), totalPages);
  const slice = SORTED.slice((p-1)*PER, p*PER);
  const canonical = p===1 ? '/all-schools' : `/all-schools/${p}`;
  const seed=hash(canonical), d=dates(seed);
  const bc=[{name:'홈',url:'/'},{name:'전체 학교',url:'/all-schools'}].concat(p>1?[{name:p+'페이지',url:canonical}]:[]);
  const pager = () => {
    const out=[]; const s=Math.max(1,p-4), e=Math.min(totalPages,p+4);
    if (p>1) out.push(`<a class="chip" href="${p-1===1?'/all-schools':'/all-schools/'+(p-1)}">← 이전</a>`);
    if (s>1) out.push(`<a class="chip" href="/all-schools">1</a>`,`<span class="chip" style="border:0">…</span>`);
    for(let i=s;i<=e;i++) out.push(`<a class="chip" style="${i===p?'background:var(--ink);color:var(--paper);border-color:var(--ink)':''}" href="${i===1?'/all-schools':'/all-schools/'+i}">${i}</a>`);
    if (e<totalPages) out.push(`<span class="chip" style="border:0">…</span>`,`<a class="chip" href="/all-schools/${totalPages}">${totalPages}</a>`);
    if (p<totalPages) out.push(`<a class="chip" href="/all-schools/${p+1}">다음 →</a>`);
    return `<div class="chips" style="margin-top:26px">${out.join('')}</div>`;
  };
  const body = thumb({file:'all-schools.jpg', kicker:'ALL SCHOOLS', title:p===1?'전국 전체 학교 목록':`전국 전체 학교 목록 (${p}/${totalPages})`, sub:`초·중·고 ${SORTED.length.toLocaleString()}개교 가나다순`})
  + `<section class="ph"><div class="wrap">${bcNav(bc)}<span class="k">🏫 All Schools</span>
   <h1>전국 전체 학교${p>1?` <span style="font-size:.55em;color:var(--ink3)">${p} / ${totalPages}</span>`:''}</h1>
   <p class="lead">전국 초·중·고 ${SORTED.length.toLocaleString()}개교를 가나다순으로 모두 정리했습니다. 학교명을 선택하면 그 학교의 국어·영어·수학·사회·과학 과외 안내로 이동합니다. 브라우저 검색(Ctrl+F 또는 ⌘+F)으로 학교명을 바로 찾을 수 있습니다.</p>
   ${dateLine(d)}
   <div class="meta"><div><dt>전체 학교</dt><dd>${SORTED.length.toLocaleString()}</dd></div><div><dt>현재 페이지</dt><dd>${p} / ${totalPages}</dd></div><div><dt>표시</dt><dd>${slice.length}개교</dd></div><div><dt>정렬</dt><dd>가나다순</dd></div></div></div></section>
   <section class="sec"><div class="wrap"><div class="sh"><span class="no">${String(p).padStart(2,'0')}</span><h2>🏫 학교 목록 <span style="font-size:13.5px;color:var(--ink3);font-weight:400">${((p-1)*PER+1).toLocaleString()} ~ ${((p-1)*PER+slice.length).toLocaleString()}번</span></h2></div>
   <div class="grid3">${slice.map(r=>`<a href="/school/${r.slug}"><div class="gt">${GEMO[r.g]} ${r.full}</div><div class="gd">${SIDO[r.se]} ${r.gk}</div></a>`).join('')}</div>
   ${pager()}</div></section>
   <section class="sec"><div class="wrap"><div class="sh"><span class="no">99</span><h2>📍 지역으로 찾기</h2></div>
   <div class="grid4">${SIDO_ORDER.map(s=>{const n=(SIDX[s]||[]).reduce((a,x)=>a+x.n,0);return `<a href="/hub/${s}"><span>${SIDO[s]}</span><em>${n.toLocaleString()}</em></a>`;}).join('')}</div></div></section>` + ctaBlock('', 11);
  return shell({
    title: p===1 ? `전국 전체 학교 목록 — 초·중·고 ${SORTED.length.toLocaleString()}개교 | ${CFG.brand}` : `전국 전체 학교 목록 ${p}페이지 — ${CFG.brand}`,
    desc:`전국 초·중·고 ${SORTED.length.toLocaleString()}개교 전체 목록(가나다순, ${p}/${totalPages}페이지). 학교명을 선택하면 국어·영어·수학·사회·과학 과외 안내로 이동합니다.`,
    keywords:'전체 학교,전국 학교 목록,초등학교 목록,중학교 목록,고등학교 목록,학교별 과외',
    canonical, body, bc, dates:d, file:'all-schools.jpg',
    itemList: slice.slice(0,50).map(r=>({name:r.full, url:'/school/'+r.slug}))});
}

