const FAVICON_B64 = '';
const APPLE_B64   = '';
function b64bin(b64){
  const bin = atob(b64); const arr = new Uint8Array(bin.length);
  for (let i=0;i<bin.length;i++) arr[i]=bin.charCodeAt(i);
  return arr;
}
function faviconIco(){ return new Response(b64bin(FAVICON_B64), {headers:{'content-type':'image/x-icon','cache-control':'public,max-age=604800'}}); }
function appleIcon(){ return new Response(b64bin(APPLE_B64), {headers:{'content-type':'image/png','cache-control':'public,max-age=604800'}}); }
function iconSvg(){
  const s = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="10" fill="#141210"/><path d="M4 46V11l13 16L32 7l15 20 13-16v35z" fill="#E8B23A"/><rect x="4" y="48" width="56" height="10" fill="#E8B23A"/><circle cx="15" cy="53" r="2.8" fill="#141210"/><circle cx="32" cy="53" r="2.8" fill="#141210"/><circle cx="49" cy="53" r="2.8" fill="#141210"/></svg>`;
  return new Response(s, {headers:{'content-type':'image/svg+xml','cache-control':'public,max-age=604800'}});
}
function manifest(){
  return new Response(JSON.stringify({name:CFG.brand,short_name:CFG.brand,start_url:'/',display:'standalone',background_color:'#FBFAF7',theme_color:'#141210',
    icons:[{src:'/icon.svg',sizes:'any',type:'image/svg+xml'},{src:'/apple-touch-icon.png',sizes:'180x180',type:'image/png'}]}),
    {headers:{'content-type':'application/manifest+json;charset=UTF-8','cache-control':'public,max-age=86400'}});
}

