/* ══════════════ 사이트맵 ══════════════ */
const SM_CHUNK = 20000;
function allUrls(){
  build();
  const a=[];
  for (const r of LIST){ a.push('/school/'+r.slug); for (const k of SUBJ_KEYS) a.push('/school/'+r.slug+'/'+k); }
  return a;
}
function staticUrls(){
  build();
  const u = ['/','/hub','/subject','/guide','/contact','/all-schools']
    .concat(SUBJ_KEYS.map(k=>'/subject/'+k))
    .concat(SIDO_ORDER.map(s=>'/hub/'+s));
  for (const se of SIDO_ORDER) for (const g of (SIDX[se]||[])) u.push(`/hub/${se}/${g.ge}`);
  const tp = Math.ceil(SORTED.length/PER);
  for (let i=2;i<=tp;i++) u.push('/all-schools/'+i);
  return u;
}
function xml(urls){
  const today = fmtISO(Date.now());
  return new Response(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${
    urls.map(u=>`<url><loc>${CFG.origin}${u}</loc><lastmod>${today}</lastmod><changefreq>weekly</changefreq><priority>${u==='/'?'1.0':(u.split('/').length>3?'0.6':'0.8')}</priority></url>`).join('')
  }</urlset>`, {headers:{'content-type':'application/xml;charset=UTF-8','cache-control':'public,max-age=86400'}});
}
function sitemapIndex(){
  const n = Math.ceil(allUrls().length / SM_CHUNK);
  const today = fmtISO(Date.now());
  const parts = [`<sitemap><loc>${CFG.origin}/sitemap-main.xml</loc><lastmod>${today}</lastmod></sitemap>`];
  for (let i=1;i<=n;i++) parts.push(`<sitemap><loc>${CFG.origin}/sitemap-${i}.xml</loc><lastmod>${today}</lastmod></sitemap>`);
  return new Response(`<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${parts.join('')}</sitemapindex>`,
    {headers:{'content-type':'application/xml;charset=UTF-8','cache-control':'public,max-age=86400'}});
}
function sitemapNaver(){ return xml(staticUrls()); }
function sitemapMain(){ return xml(staticUrls()); }
function sitemapChunk(i){
  const all = allUrls(); const start=(i-1)*SM_CHUNK;
  if (start >= all.length) return null;
  return xml(all.slice(start, start+SM_CHUNK));
}

